//! The file types MatLivre opens: registered for the current user when it is installed or
//! updated, removed when it is uninstalled. Generated by Release Manager from file-types under
//! [package.metadata.release-manager] in Cargo.toml: change them there and run "Set up
//! auto-update" again, which rewrites this file.

/// Each type: its extension (without the dot), its description, and its icon in the install's
/// file-icons folder, or None for the program's own icon.
const FILE_TYPES: &[(&str, &str, Option<&str>)] = &[
    ("mlx", "MatLivre Live Script", Some("mlx.ico")),
    ("m", "MatLivre Script", Some("m.ico")),
];

/// What the registry knows the program by: its ProgIDs are matlivre.<extension>.
const PROG_ID: &str = "matlivre";

/// The program's name in Windows' "Open with" list.
const TITLE: &str = "MatLivre";

/// Adds the registration to Velopack's install, update and uninstall hooks (Windows only).
pub fn with_hooks<'a>(app: velopack::VelopackApp<'a>) -> velopack::VelopackApp<'a> {
    #[cfg(windows)]
    {
        app.on_after_install_fast_callback(|_| registry::register(FILE_TYPES))
            .on_after_update_fast_callback(|_| registry::register(FILE_TYPES))
            .on_before_uninstall_fast_callback(|_| registry::register(&[]))
    }
    #[cfg(not(windows))]
    {
        app
    }
}

#[cfg(windows)]
mod registry {
    use super::{PROG_ID, TITLE};
    use std::ffi::c_void;

    type Hkey = isize;
    const HKEY_CURRENT_USER: Hkey = 0x8000_0001u32 as i32 as isize;
    const KEY_ALL_ACCESS: u32 = 0xF003F;
    const KEY_READ: u32 = 0x20019;
    const REG_SZ: u32 = 1;
    const RRF_RT_REG_SZ: u32 = 0x2;
    const SHCNE_ASSOCCHANGED: i32 = 0x0800_0000;

    /// Where a type's ProgID keeps the program the extension opened with before this one.
    const PREVIOUS: &str = "PreviousDefault";

    #[link(name = "advapi32")]
    extern "system" {
        fn RegCreateKeyExW(key: Hkey, sub: *const u16, reserved: u32, class: *const u16, options: u32, sam: u32, security: *const c_void, result: *mut Hkey, disposition: *mut u32) -> i32;
        fn RegOpenKeyExW(key: Hkey, sub: *const u16, options: u32, sam: u32, result: *mut Hkey) -> i32;
        fn RegSetValueExW(key: Hkey, name: *const u16, reserved: u32, kind: u32, data: *const u8, size: u32) -> i32;
        fn RegGetValueW(key: Hkey, sub: *const u16, name: *const u16, flags: u32, kind: *mut u32, data: *mut c_void, size: *mut u32) -> i32;
        fn RegEnumValueW(key: Hkey, index: u32, name: *mut u16, name_len: *mut u32, reserved: *const u32, kind: *mut u32, data: *mut u8, size: *mut u32) -> i32;
        fn RegDeleteKeyValueW(key: Hkey, sub: *const u16, name: *const u16) -> i32;
        fn RegDeleteTreeW(key: Hkey, sub: *const u16) -> i32;
        fn RegCloseKey(key: Hkey) -> i32;
        fn RegQueryInfoKeyW(key: Hkey, class: *mut u16, class_len: *mut u32, reserved: *const u32, subkeys: *mut u32, max_subkey: *mut u32, max_class: *mut u32, values: *mut u32, max_value_name: *mut u32, max_value: *mut u32, security: *mut u32, written: *mut c_void) -> i32;
    }

    #[link(name = "shell32")]
    extern "system" {
        fn SHChangeNotify(event: i32, flags: u32, item1: *const c_void, item2: *const c_void);
    }

    fn wide(s: &str) -> Vec<u16> {
        s.encode_utf16().chain(Some(0)).collect()
    }

    /// Sets a string value (None: the key's default value), creating the key.
    fn set(sub: &str, name: Option<&str>, value: &str) {
        let mut key: Hkey = 0;
        unsafe {
            if RegCreateKeyExW(HKEY_CURRENT_USER, wide(sub).as_ptr(), 0, std::ptr::null(), 0, KEY_ALL_ACCESS, std::ptr::null(), &mut key, std::ptr::null_mut()) != 0 {
                return;
            }
            let data = wide(value);
            let name = name.map(wide);
            RegSetValueExW(key, name.as_ref().map_or(std::ptr::null(), |n| n.as_ptr()), 0, REG_SZ, data.as_ptr() as *const u8, (data.len() * 2) as u32);
            RegCloseKey(key);
        }
    }

    /// A string value, or None when it is missing.
    fn get(sub: &str, name: Option<&str>) -> Option<String> {
        let mut buffer = [0u16; 1024];
        let mut size = (buffer.len() * 2) as u32;
        let name = name.map(wide);
        let found = unsafe {
            RegGetValueW(HKEY_CURRENT_USER, wide(sub).as_ptr(), name.as_ref().map_or(std::ptr::null(), |n| n.as_ptr()), RRF_RT_REG_SZ, std::ptr::null_mut(), buffer.as_mut_ptr() as *mut c_void, &mut size)
        };
        if found != 0 {
            return None;
        }
        let len = (size as usize / 2).saturating_sub(1);
        Some(String::from_utf16_lossy(&buffer[..len]))
    }

    /// The names of a key's values (the extensions under SupportedTypes).
    fn value_names(sub: &str) -> Vec<String> {
        let mut names = Vec::new();
        let mut key: Hkey = 0;
        unsafe {
            if RegOpenKeyExW(HKEY_CURRENT_USER, wide(sub).as_ptr(), 0, KEY_READ, &mut key) != 0 {
                return names;
            }
            let mut index = 0;
            loop {
                let mut name = [0u16; 256];
                let mut len = name.len() as u32;
                if RegEnumValueW(key, index, name.as_mut_ptr(), &mut len, std::ptr::null(), std::ptr::null_mut(), std::ptr::null_mut(), std::ptr::null_mut()) != 0 {
                    break;
                }
                names.push(String::from_utf16_lossy(&name[..len as usize]));
                index += 1;
            }
            RegCloseKey(key);
        }
        names
    }

    fn delete_value(sub: &str, name: Option<&str>) {
        let name = name.map(wide);
        unsafe {
            RegDeleteKeyValueW(HKEY_CURRENT_USER, wide(sub).as_ptr(), name.as_ref().map_or(std::ptr::null(), |n| n.as_ptr()));
        }
    }

    /// Deletes a key when nothing is left in it: no values (not even a default) and no subkeys.
    fn delete_if_empty(sub: &str) {
        let mut key: Hkey = 0;
        let (mut subkeys, mut values) = (0u32, 0u32);
        unsafe {
            if RegOpenKeyExW(HKEY_CURRENT_USER, wide(sub).as_ptr(), 0, KEY_READ, &mut key) != 0 {
                return;
            }
            let ok = RegQueryInfoKeyW(key, std::ptr::null_mut(), std::ptr::null_mut(), std::ptr::null(), &mut subkeys, std::ptr::null_mut(), std::ptr::null_mut(), &mut values, std::ptr::null_mut(), std::ptr::null_mut(), std::ptr::null_mut(), std::ptr::null_mut()) == 0;
            RegCloseKey(key);
            if ok && subkeys == 0 && values == 0 {
                RegDeleteTreeW(HKEY_CURRENT_USER, wide(sub).as_ptr());
            }
        }
    }

    /// Deletes a key with everything under it.
    fn delete_tree(sub: &str) {
        unsafe {
            RegDeleteTreeW(HKEY_CURRENT_USER, wide(sub).as_ptr());
        }
    }

    /// Makes the registry match `types`: each one opens with this program and shows its icon;
    /// types registered before but no longer listed are taken back. An empty list removes them all.
    pub fn register(types: &[(&str, &str, Option<&str>)]) {
        let Ok(exe) = std::env::current_exe() else { return };
        let exe_name = exe.file_name().map(|n| n.to_string_lossy().into_owned()).unwrap_or_default();
        let folder = exe.parent().map(|p| p.to_path_buf()).unwrap_or_default();
        let exe = exe.to_string_lossy().into_owned();
        let application = format!("Software\\Classes\\Applications\\{exe_name}");
        let supported = format!("{application}\\SupportedTypes");

        // Types this program registered before and no longer lists.
        for old in value_names(&supported) {
            let ext = old.trim_start_matches('.').to_string();
            if !types.iter().any(|(e, _, _)| e.eq_ignore_ascii_case(&ext)) {
                remove(&ext, &supported);
            }
        }

        for (ext, description, icon) in types {
            let prog_id = format!("{PROG_ID}.{ext}");
            let class = format!("Software\\Classes\\{prog_id}");
            set(&class, None, description);
            let icon = match icon {
                Some(file) => folder.join("file-icons").join(file).to_string_lossy().into_owned(),
                None => format!("\"{exe}\",0"),
            };
            set(&format!("{class}\\DefaultIcon"), None, &icon);
            set(&format!("{class}\\shell\\open\\command"), None, &format!("\"{exe}\" \"%1\""));
            // The type opens with this program, unless the user picked another for it in Windows.
            // The program it opened with before is kept, to give it back on uninstall.
            let extension = format!("Software\\Classes\\.{ext}");
            match get(&extension, None) {
                Some(previous) if !previous.is_empty() && previous != prog_id => set(&class, Some(PREVIOUS), &previous),
                _ => {}
            }
            set(&extension, None, &prog_id);
            set(&format!("Software\\Classes\\.{ext}\\OpenWithProgids"), Some(&prog_id), "");
            set(&supported, Some(&format!(".{ext}")), "");
        }

        if types.is_empty() {
            delete_tree(&application);
        } else {
            set(&application, Some("FriendlyAppName"), TITLE);
            set(&format!("{application}\\shell\\open\\command"), None, &format!("\"{exe}\" \"%1\""));
        }
        // Explorer shows the new icons and "Open with" at once.
        unsafe { SHChangeNotify(SHCNE_ASSOCCHANGED, 0, std::ptr::null(), std::ptr::null()) };
    }

    /// Takes one type back: its ProgID, and the extension's link to it when it is still ours
    /// (another program may have been made its default since).
    fn remove(ext: &str, supported: &str) {
        let prog_id = format!("{PROG_ID}.{ext}");
        let class = format!("Software\\Classes\\{prog_id}");
        let previous = get(&class, Some(PREVIOUS));
        delete_tree(&class);
        let extension = format!("Software\\Classes\\.{ext}");
        if get(&extension, None).as_deref() == Some(prog_id.as_str()) {
            match previous {
                Some(previous) => set(&extension, None, &previous),
                None => delete_value(&extension, None),
            }
        }
        delete_value(&format!("{extension}\\OpenWithProgids"), Some(&prog_id));
        delete_value(supported, Some(&format!(".{ext}")));
        // The extension's keys go too when no other program uses them.
        delete_if_empty(&format!("{extension}\\OpenWithProgids"));
        delete_if_empty(&extension);
    }
}
